$string['settings:embed_apibaseurl'] = 'Embedding API Base URL';
$string['settings:embed_apibaseurl_desc'] = 'Base URL for the embedding API. Leave blank for OpenAI default. For Ollama: http://localhost:11434/api';
$string['settings:embed_apikey'] = 'Embedding API Key';
$string['settings:embed_apikey_desc'] = 'API key for the embedding provider. Can be different from the chat API key. Not required for Ollama.';
$string['settings:embed_dimensions'] = 'Embedding Dimensions';
$string['settings:embed_dimensions_desc'] = 'Largeur du vecteur d\'embedding, qui doit être une largeur que le modèle propose réellement. OpenAI text-embedding-3-small : 1536. nomic-embed-text : 768. Les modèles Voyage acceptent 256, 512, 1024 et 2048 (la valeur native 1024 est omise de la requête) ; une largeur invalide est omise au lieu d\'être envoyée, si bien que vous obtiendriez silencieusement la largeur native au lieu de celle demandée. voyage-4-large en 2048 est la configuration mesurée — +14,0 points de pourcentage de rappel sur des requêtes réalistes, pour moins de 4 dollars par mois — et son adoption exige une RÉINDEXATION COMPLÈTE, car le récupérateur refuse de noter une requête face à des fragments issus d\'un autre espace d\'embedding. Utilisez la migration de modèle d\'embedding sur la page d\'index RAG plutôt que de changer cette valeur d\'abord.';
$string['settings:embed_model'] = 'Embedding Model';
$string['settings:embed_model_desc'] = 'Model to use for generating embeddings. OpenAI default: text-embedding-3-small. Ollama example: nomic-embed-text.';
$string['settings:embed_provider'] = 'Embedding Provider';
$string['settings:embed_provider_desc'] = 'The API provider used to generate text embeddings for RAG indexing and retrieval.';
$string['settings:embed_provider_ollama'] = 'Ollama (local, e.g. nomic-embed-text)';
$string['settings:embed_provider_openai'] = 'OpenAI (text-embedding-3-small)';
$string['settings:hide_on_quiz_for_staff'] = 'Hide [[tutorshort]] on quiz pages for staff';
