$string['settings:model_desc_dynamic'] = 'Leave blank to use the provider\'s default model automatically. Each provider has a built-in default that stays current (e.g. gpt-4o for OpenAI, claude-sonnet-4 for Claude, mistral-large-latest for Mistral). Only enter a model name if you want to override the default. If a model is misspelled or deprecated, [[tutorshort]] will automatically fall back to the provider\'s default.';
$string['settings:provider_gemini'] = 'Google Gemini';
$string['settings:quiz_hide_heading'] = 'Quiz Page Visibility';
$string['settings:quiz_hide_heading_desc'] = 'Control whether the [[tutorshort]] widget appears on Moodle quiz pages. This is stricter than the built-in summative quiz lock, which only disables chat during graded quizzes. These settings completely hide the widget on all quiz pages.';
$string['settings:rag_chunksize'] = 'Chunk Size (words)';
$string['settings:rag_chunksize_desc'] = 'Target number of words per content chunk when indexing course material. Smaller chunks are more precise; larger chunks provide more context.';
$string['settings:rag_return_scope'] = 'Portée de retour de la récupération';
$string['settings:rag_return_scope_desc'] = 'Ce qui est injecté pour chaque résultat récupéré. "chunk" (par défaut) injecte le segment correspondant d\'environ 400 mots. "window" injecte le segment correspondant ainsi que les segments voisins de la même page. "page" injecte la page de module entière à laquelle appartient le résultat. window/page sont utiles lorsqu\'une réponse s\'étend sur toute une page, au prix d\'une invite plus grande.';
$string['settings:rag_window_size'] = 'Taille de la fenêtre de récupération';
$string['settings:rag_window_size_desc'] = 'Pour la portée de retour "window" : nombre de segments voisins à inclure de chaque côté d\'un segment correspondant. Par défaut 1.';
$string['settings:rag_parent_max_chars'] = 'Plafond du passage parent (caractères)';
$string['settings:rag_parent_max_chars_desc'] = 'Nombre maximal de caractères pour un passage window/page étendu. Les pages dépassant le plafond reviennent à une fenêtre, puis au segment unique. Par défaut 6000.';
$string['settings:rag_enabled'] = 'Enable RAG (Semantic Search)';
$string['settings:rag_enabled_desc'] = 'When enabled, the AI tutor uses semantic search to retrieve relevant course content for each query instead of stuffing all content into the system prompt.';
$string['settings:rag_heading'] = 'RAG / Semantic Search';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: index course content as embeddings and retrieve only the most relevant chunks at query time. Reduces token usage and supports all content types. Requires an embedding API.';
$string['settings:rag_topk'] = 'Top-K Chunks';
$string['settings:rag_topk_desc'] = 'Number of most relevant chunks to retrieve per user query and inject into the system prompt.';
$string['settings:realtime_apikey'] = 'OpenAI API Key (Voice & TTS)';
