$string['settings:embed_input_type_asymmetric'] = 'Asymétrique requête/document (recommandé)';
$string['settings:embed_input_type_mode'] = 'Type d\'entrée d\'embedding';
$string['settings:embed_input_type_mode_desc'] = 'Embeddings Voyage uniquement. Voyage projette le texte différemment selon qu\'il s\'agit d\'une requête ou d\'un document. « Asymétrique » envoie input_type=query lors de la recherche et input_type=document lors de l\'indexation. C\'est ce que le fournisseur prévoit et ce qui mesure le mieux sur ce corpus : utiliser la projection document du côté requête a coûté 30,8 points de pourcentage de rappel et a perdu dans toutes les tranches de longueur de requête (2026-08-21, voyage-3.5, jeu calqué sur la production). « Espace partagé » envoie input_type=document des deux côtés ; il récupère nettement moins bien et n\'existe que comme assurance de migration, car une projection unique permet de changer de modèle de requête sans réencoder le corpus. Choisissez asymétrique sauf si vous êtes en pleine migration. Ce changement ne nécessite pas de réindexation : seule la projection côté requête change. Ce n\'est PAS l\'appariement asymétrique de modèles (indexer avec un modèle Voyage plus grand que celui utilisé pour les requêtes) : c\'est la technique différente qui n\'a pas pu être reproduite deux fois sur ce corpus, et elle dépend du paramètre de modèle de requête, pas de celui-ci.';
$string['settings:embed_input_type_shared'] = 'Espace partagé (assurance de migration ; récupération moins bonne)';
$string['settings:embed_migration_heading'] = 'Migration du modèle d\'embedding';
$string['settings:embed_migration_heading_desc'] = 'Changer le modèle d\'embedding ou sa largeur invalide tous les vecteurs stockés : le récupérateur refuse de noter une requête face à des fragments issus d\'un autre espace d\'embedding, si bien qu\'un cours ne récupère rien plutôt que de mal récupérer. Ces paramètres décrivent le modèle VERS lequel vous migrez. Les cours sont ensuite réencodés un par un depuis la page d\'index RAG, en écrivant les nouveaux vecteurs à côté des anciens, et les paramètres actifs ci-dessus continuent d\'assurer la récupération jusqu\'à ce que vous les changiez vous-même.';
$string['settings:embed_migration_provider_inherit'] = 'Utiliser le fournisseur configuré ci-dessus';
$string['settings:embed_migration_target_apikey'] = 'Clé API du fournisseur cible';
$string['settings:embed_migration_target_apikey_desc'] = 'Nécessaire uniquement lorsque le fournisseur cible diffère de celui configuré ci-dessus. Vide signifie utiliser la clé d\'embedding existante.';
$string['settings:embed_migration_target_dimensions'] = 'Largeur d\'embedding cible';
$string['settings:embed_migration_target_dimensions_desc'] = 'Largeur de vecteur à demander pendant la migration. 0 signifie la largeur native du modèle. Voyage accepte 256, 512, 1024 et 2048 ; une largeur que le modèle ne propose pas est omise de la requête au lieu d\'être envoyée, ce qui vous donnerait silencieusement la largeur native au lieu de celle demandée.';
$string['settings:embed_migration_target_model'] = 'Modèle d\'embedding cible';
$string['settings:embed_migration_target_model_desc'] = 'Nom du modèle avec lequel encoder pendant la migration, par exemple <code>voyage-4-large</code>. Vide signifie qu\'aucune migration n\'est configurée et que la page d\'index RAG n\'en propose aucune.';
$string['settings:embed_migration_target_provider'] = 'Fournisseur d\'embedding cible';
$string['settings:embed_migration_target_provider_desc'] = 'Laissez vide pour migrer au sein du fournisseur déjà configuré ci-dessus.';
$string['settings:rerank_min_query_chars'] = 'Reclassement : longueur minimale de requête';
$string['settings:rerank_min_query_chars_desc'] = 'Ignorer le reclasseur pour les requêtes de cette longueur en caractères ou moins. Les requêtes courtes ont une forme de mots-clés et le reclasseur n\'ajoute presque rien à la similarité cosinus sur deux ou trois mots. Mesuré sur le jeu de fixtures RAG : un filtre à 50 a obtenu 67,7 % de rappel contre 67,2 % pour un reclassement systématique, pour environ un tiers du coût. Réglez sur 0 pour reclasser toutes les requêtes. Les reclassements ignorés sont consignés dans le journal des messages sous la forme « [Rerank skipped: short_query] », ce qui vous permet de vérifier que le filtre fonctionne.';
$string['settings:spend_export_key'] = 'Clé d\'export des dépenses';
$string['settings:spend_export_key_desc'] = 'Clé Bearer pour le point de terminaison mensuel d\'export des dépenses IA à l\'adresse <code>/local/ai_course_assistant/spend_export.php</code>, que le tableau de bord des dépenses interroge une fois par mois. Laissez vide pour désactiver le point de terminaison — il renvoie alors 404 à toute requête. La clé est acceptée UNIQUEMENT dans un en-tête <code>Authorization: Bearer</code>, jamais dans l\'URL. Générez une valeur longue et aléatoire ; quiconque la détient peut lire les dépenses IA de tout le site. Chaque export réussi est consigné dans le journal d\'audit du plugin.';
$string['task:migrate_course_embeddings'] = 'Migrer un cours vers un nouveau modèle d\'embedding';
$string['task:model_price_drift_check'] = 'Vérification de dérive tarifaire des modèles';
$string['task:run_model_benchmark'] = 'Évaluer un modèle';
